#pragma once

// Tables generated by tools/embed_assets.py: WebAssembly images for the local
// registry and pre-compressed web assets served by the ingress.

#include "runtime/image_registry.hpp"

#include <cstddef>
#include <cstdint>

namespace kube32::embedded {

struct EmbeddedAsset {
    const char* app;           // "tessera"
    const char* path;          // "/", "/app.js", "/styles.css"
    const uint8_t* data;
    size_t len;
    const char* content_type;
    bool gzip;                 // true when data is already gzip-compressed
};

const kube32::runtime::EmbeddedImage* images(size_t& count);
const EmbeddedAsset* assets(size_t& count);

} // namespace kube32::embedded
